//! 🫴️ One explicitly installed caller slot retains returned encoder ownership until physical drain.
use crate::{ErasedSnapshotRetirement,RetainedWorkOutcome,ValueError,retained_clone::{RetainedCloneGrant,RetainedCloneStep,RetainedCloneProgress}};
use std::mem::ManuallyDrop;
static RECIPIENT_IDS:std::sync::atomic::AtomicU64=std::sync::atomic::AtomicU64::new(1);

/// 🪑️ Stack-resident recipient capacity is admitted before a encoder can create partial owners.
pub struct NativeEncodeRetirementRecipient{pub(super) owner:ManuallyDrop<Option<Box<dyn ErasedSnapshotRetirement>>>,ticket:ManuallyDrop<semio_framework_value_retirement::FactoryTicketClose>,original:Option<(crate::NativeAllocationIdentity,Option<u64>,semio_framework_value_control_contract::OriginalWorkBindingIdentity,usize)>,pub(super) reserved:bool,pub(super) identity:u64}
impl NativeEncodeRetirementRecipient{
    /// 🈳️ Creates the single empty caller-owned return slot without heap allocation.
    pub fn new()->Self{let identity=RECIPIENT_IDS.try_update(std::sync::atomic::Ordering::Relaxed,std::sync::atomic::Ordering::Relaxed,|identity|identity.checked_add(1)).expect("native recipient identity space exhausted");Self{owner:ManuallyDrop::new(None),ticket:ManuallyDrop::new(semio_framework_value_retirement::FactoryTicketClose::vacant()),original:None,reserved:false,identity}}
    /// 🪪️ Identifies the exact caller-owned retirement port.
    pub fn identity(&self)->u64{self.identity}
    /// 👓️ Reports retained ownership without borrowing or transferring the actual owner.
    pub fn has_owner(&self)->bool{self.owner.is_some()||!self.ticket.is_empty()||self.original.is_some()}
    pub(super) fn has_pending_close(&self)->bool{!self.ticket.is_empty()||self.original.is_some()}
}
impl ErasedSnapshotRetirement for NativeEncodeRetirementRecipient{
 fn close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>,ValueError>{if !self.ticket.is_empty()||self.original.is_some(){return Err(ValueError::invariant("encoder recipient requires original close recovery"))}if !self.reserved{return self.ticket.close_into(&mut self.owner,body,effect,reply)}let d=crate::RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()};if !crate::retained_clone::retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}match effect.performed(1){Ok(true)=>{},Ok(false)=>return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"encoder recipient close exceeded Work").into()))),Err(error)=>return Ok(reply.complete(Err(error.into())))}self.reserved=false;Ok(reply.complete(Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))))}
 fn recover_close_into<'r>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>,ValueError>{if self.original.is_some(){return Err(ValueError::invariant("encoder recipient recovery requires original loan"))}if self.reserved{return Err(ValueError::invariant("encoder recipient recovery has no selected child"))}self.ticket.recover_close_into(&mut self.owner,body,effect,reply)}
 fn close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>,ValueError>{let work=original.original_work().binding_identity()?;if !work.matches_effect(effect){return Err(ValueError::invariant("encoder recipient original Work changed"))}if !self.ticket.is_empty()||self.original.is_some(){return Err(ValueError::invariant("encoder recipient requires original close recovery"))}if self.reserved{return Err(ValueError::invariant("encoder recipient original close has no selected child"))}let key=(original.ledger_identity(),original.retirement_recipient_identity(),work,body);let mut scope=reply.scope(&mut self.original,key)?;let done=self.ticket.close_original_into(&mut self.owner,original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn recover_close_original_into<'r>(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::OriginalEffectReply<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>)->Result<crate::OriginalEffectReplyComplete<'r,RetainedCloneStep,semio_framework_value_retirement::OriginalRetirementFailure>,ValueError>{let work=original.original_work().binding_identity()?;if !work.matches_effect(effect){return Err(ValueError::invariant("encoder recipient original Work changed"))}let key=(original.ledger_identity(),original.retirement_recipient_identity(),work,body);if self.original!=Some(key){return Err(ValueError::invariant("encoder recipient original loan or body changed"))}let mut scope=reply.scope(&mut self.original,key)?;let done=self.ticket.recover_close_original_into(&mut self.owner,original,body,effect,scope.borrow()?)?;drop(done);Ok(scope.forwarded())}
 fn next_computational_work(&self,body:usize)->Result<u64,ValueError>{if self.original.is_some_and(|key|key.3!=body){return Err(ValueError::invariant("encoder recipient changed original body"))}if self.original.is_some()&&self.ticket.is_empty(){return Err(ValueError::invariant("encoder recipient original action lost its child"))}if self.reserved{return Ok(1)}self.ticket.next_work(&self.owner,body)}
 fn requires_original_birth(&self)->bool{!self.reserved&&self.ticket.is_empty()&&self.original.is_none()&&self.owner.as_ref().is_some_and(|owner|owner.requires_original_birth())}
 fn close_original_birth_step(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value_retirement::OriginalRetirementPoll{match self.owner.as_mut(){Some(owner)if !self.reserved&&self.ticket.is_empty()&&self.original.is_none()=>owner.close_original_birth_step(original,grant),_=>semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"encoder has no selected original birth").into()),work:0})}}
 fn requires_original_control(&self)->bool{!self.reserved&&(self.original.is_some()||self.ticket.pending_original_control().unwrap_or_else(||self.owner.as_ref().is_some_and(|owner|owner.requires_original_control())))}
 fn close_original_step(&mut self,original:&mut semio_framework_value_retirement_contract::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{if !self.ticket.is_empty()||self.original.is_some(){return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("encoder recipient retains borrowed close action").into()),work:0})}semio_framework_value_retirement::close_factory_ticket_original(&mut self.owner,original,body,effect)}
 fn close_step_controlled(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,control:&mut dyn semio_framework_value_retirement::OriginalRetirementControl)->semio_framework_value_retirement::OriginalRetirementPoll{if !self.ticket.is_empty()||self.original.is_some(){return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("encoder recipient retains borrowed close action").into()),work:0})}semio_framework_value_retirement::close_factory_ticket_controlled(&mut self.owner,body,effect,control)}
 fn visit_original(&mut self,identity:std::any::TypeId,visitor:&mut dyn FnMut(&mut dyn std::any::Any))->bool{self.owner.as_mut().is_some_and(|owner|owner.visit_original(identity,visitor))}
 fn next_demand(&self,body:usize)->Result<crate::RetirementDemand,ValueError>{
  if self.original.is_some_and(|key|key.3!=body){return Err(ValueError::invariant("encoder recipient changed original body"))}if self.original.is_some()&&self.ticket.is_empty(){return Err(ValueError::invariant("encoder recipient original action lost its child"))}if self.reserved{Ok(crate::RetirementDemand{copy_bytes:size_of::<bool>(),depth:1,..Default::default()})}else{self.ticket.next_demand(&self.owner,body)}
 }
 fn close_step(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value_retirement::OriginalRetirementPoll{if !self.ticket.is_empty()||self.original.is_some(){return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::invariant("encoder recipient retains borrowed close action").into()),work:0})}let grant=effect.grant();
  if !self.reserved{return crate::close_factory_ticket(&mut self.owner,body,effect)}
  if grant.maximum_items==0{return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}
  if grant.maximum_depth==0{return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::DepthLimit,"native return slot close requires admitted depth").into()),work:0})}
  if effect.maximum_work_units()==0||grant.maximum_copy_bytes<size_of::<bool>(){return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(Default::default())),work:0})}
  match effect.performed(1){Ok(true)=>{},Ok(false)=>return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native return slot work exceeded its original quote").into()),work:1}),Err(error)=>return semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(error.into()),work:1})}
  self.reserved=false;
  semio_framework_value_control_contract::RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:size_of::<bool>(),..Default::default()})),work:1})
 }
 fn terminal_is_empty(&self)->bool{!self.reserved&&self.owner.is_none()&&self.ticket.is_empty()&&self.original.is_none()}
 fn next_copy_byte_demand(&self)->Result<usize,ValueError>{self.next_demand(0).map(|d|d.copy_bytes)}
 fn next_capacity_byte_demand(&self,copy:usize)->Result<usize,ValueError>{self.next_demand(copy).map(|d|d.capacity_bytes)}
 fn next_release_byte_demand(&self)->Result<usize,ValueError>{self.next_demand(0).map(|d|d.release_bytes)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{self.next_demand(0).map(|d|d.depth)}
}
impl Drop for NativeEncodeRetirementRecipient{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"encoder recipient retains returned physical ownership");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.owner);ManuallyDrop::drop(&mut self.ticket);}}}}
